import {
  WixDataAsyncByFilterOptions,
  WixDataAsyncJob,
  WixDataBulkResult,
  WixDataItem,
} from '../types'
import {
  WixDataBulkPatch,
  WixDataBulkPatchOptions,
  WixDataPatch,
  WixDataPatchByFilter,
  WixDataPatchOptions,
} from '../WixDataPatch'
import { FieldModification } from '../FieldModification'
import { BaseFieldModificationsBuilder } from './BaseFieldModificationsBuilder'

interface BulkPatchParams {
  collectionName: string
  itemIds: string[]
  invalidArguments: string[]
  fieldModifications: FieldModification[]
}

interface PatchParams {
  collectionName: string
  itemId: string
  invalidArguments: string[]
  fieldModifications: FieldModification[]
}

interface PatchByFilterParams {
  collectionName: string
  filter: Record<string, any>
  invalidArguments: string[]
  fieldModifications: FieldModification[]
}

type OnRun = (
  args: IArguments,
  params: PatchParams,
  options?: WixDataPatchOptions
) => Promise<WixDataItem>

type OnBulkRun = (
  args: IArguments,
  params: BulkPatchParams,
  options?: WixDataBulkPatchOptions
) => Promise<WixDataBulkResult>

type OnPatchByFilterRun = (
  args: IArguments,
  params: PatchByFilterParams,
  options?: WixDataAsyncByFilterOptions
) => Promise<WixDataAsyncJob>

export class WixDataBulkPatchImpl
  extends BaseFieldModificationsBuilder<WixDataBulkPatchImpl>
  implements WixDataBulkPatch
{
  private readonly onRun: OnBulkRun
  private readonly collectionName: string
  readonly itemIds: string[]

  constructor(origin: {
    collectionName: string
    itemIds: string[]
    invalidArguments?: string[]
    fieldModifications?: FieldModification[]
    onRun: OnBulkRun
  }) {
    super(origin)
    this.collectionName = origin.collectionName
    this.onRun = origin.onRun
    this.itemIds = origin.itemIds
  }

  protected copy(params: {
    invalidArguments?: string[]
    addFieldModification: FieldModification
  }): WixDataBulkPatchImpl {
    return new WixDataBulkPatchImpl({
      ...this,
      collectionName: this.collectionName,
      invalidArguments: params.invalidArguments ?? this.ownInvalidArguments,
      fieldModifications: [
        ...this.fieldModifications,
        ...[params.addFieldModification],
      ],
      onRun: this.onRun,
    })
  }

  run(options?: WixDataBulkPatchOptions): Promise<WixDataBulkResult> {
    return this.onRun(
      arguments,
      {
        collectionName: this.collectionName,
        itemIds: this.itemIds,
        invalidArguments: this.ownInvalidArguments,
        fieldModifications: this.fieldModifications,
      },
      options
    )
  }
}

